bad:
// Different naming for the same concept
const user_id = 12;
const customerId = 18;

good:
// One naming convention across the module
const userId = 12;
const customerId = 18;

bad:
{
  "compilerOptions": { "strict": false }
}

good:
{
  "compilerOptions": {
    "strict": true,
    "noImplicitReturns": true,
    "noUnusedLocals": true,
    "forceConsistentCasingInFileNames": true
  }
}

bad:
function label(value: any) {
  return value.toUpperCase();
}

good:
function label(value: unknown): string {
  return typeof value === "string"
    ? value.toUpperCase()
    : "Unknown";
}

type JobStatus = "queued" | "running" | "finished";
type Job = { status: JobStatus };
const job: Job = { status: "finished" };

const retentionDays = 30;
function isExpired(ageInDays: number) {
  return ageInDays >= retentionDays;
}

type Profile = { name: string; email: string };
type ProfileUpdate = Partial<Profile>;
type PublicProfile = Pick<Profile, "name">;

bad:
var total = 0;
for (var index = 0; index < 3; index++) {
  total += index;
}

good:
let total = 0;
for (let index = 0; index < 3; index++) {
  total += index;
}
const result = total;

bad:
const input = "0";
if (input == 0) {
  console.log("Matched after coercion");
}

good:
const input = "0";
if (input === "0") {
  console.log("Matched a string");
}

export type User = { name: string };
export function greeting(user: User): string {
  return `Hello, ${user.name}`;
}

bad:
function name(user?: { active: boolean; name: string }) {
  if (user) {
    if (user.active) {
      return user.name;
    }
  }
  return "Guest";
}

good:
function name(user?: { active: boolean; name: string }) {
  if (!user?.active) return "Guest";
  return user.name;
}

type ExportOptions = {
  format: "csv" | "json";
  name: string;
  includeArchived?: boolean;
};
function exportReport(options: ExportOptions) {}
exportReport({ format: "csv", name: "orders" });

bad:
// An assumed micro-optimization without a measured problem
for (let index = 0, size = values.length; index < size; index++) {
  consume(values[index]);
}

good:
// Choose this when you need to stop after a match.
for (const value of values) {
  if (matches(value)) {
    consume(value);
    break;
  }
}

bad:
type Profile = { name: string };
const profile = JSON.parse(payload) as Profile;
console.log(profile.name.toUpperCase());

good:
const value: unknown = JSON.parse(payload);
if (
  typeof value !== "object" || value === null ||
  !("name" in value) || typeof value.name !== "string"
) {
  throw new Error("Expected a profile name");
}
console.log(value.name.toUpperCase());

bad:
if (isReady)
  start();
  recordStart();

good:
if (isReady) {
  start();
  recordStart();
}

bad:
function pageSize(size?: number) {
  return size || 25;
}

good:
function pageSize(size = 25): number {
  return size;
}

bad:
function label(state: string) {
  switch (state) {
    case "ready": return "Ready";
  }
}

good:
type State = "ready" | "waiting";
function label(state: State): string {
  switch (state) {
    case "ready": return "Ready";
    case "waiting": return "Waiting";
    default: {
      const unexpected: never = state;
      throw new Error(`Unexpected state: ${unexpected}`);
    }
  }
}

bad:
let title: string;
// Unrelated work happens here.
title = "Report";

good:
function* range(start: number, end: number) {
  for (let value = start; value < end; value++) {
    yield value;
  }
}
for (const value of range(1, 4)) {
  console.log(value);
}

bad:
let balance = 100;
function addPayment(amount: number) {
  balance += amount;
}

good:
function addPayment(balance: number, amount: number): number {
  return balance + amount;
}

bad:
function rename(user: { name: string }, name: string) {
  user.name = name;
  return user;
}

good:
function rename(user: Readonly<{ name: string }>, name: string) {
  return { ...user, name };
}

bad:
function icon(status: "queued" | "running") {
  if (status === "queued") return "clock";
  if (status === "running") return "spinner";
}

good:
const icons = { queued: "clock", running: "spinner" } as const;
function icon(status: keyof typeof icons) {
  return icons[status];
}

bad:
try {
  await saveReport();
} catch {
  // Ignore the failure.
}

good:
try {
  await saveReport();
} catch (error: unknown) {
  const message = error instanceof Error ? error.message : String(error);
  throw new Error(`Could not save report: ${message}`);
}

bad:
loadUser(id, user => {
  loadOrders(user.id, orders => {
    render(user, orders);
  });
});

good:
const user = await loadUser(id);
const orders = await loadOrders(user.id);
render(user, orders);

bad:
if (navigator.userAgent.includes("Chrome")) {
  enableWorkerFeature();
}

good:
if (typeof Worker !== "undefined") {
